import React, { useEffect, useState } from "react";
import api from "../services/api";

const MonitoringWidget = () => {
  const [metrics, setMetrics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Function to fetch metrics data from the backend
  const fetchMetrics = async () => {
    try {
      const response = await api.get("/api/agent/metrics/"); // Correct API endpoint
      console.log("Fetched Metrics Data:", response.data); // Debugging output

      if (response.data.length > 0) {
        setMetrics(response.data);
        setLoading(false);
      } else {
        setError("No metrics available.");
        setLoading(false);
      }
    } catch (err) {
      console.error("Error fetching metrics:", err);
      setError("Failed to fetch metrics");
      setLoading(false);
    }
  };

  // Polling setup to fetch metrics every 10 seconds
  useEffect(() => {
    fetchMetrics(); // Fetch immediately on mount
    const interval = setInterval(fetchMetrics, 10000); // Poll every 10 seconds

    return () => clearInterval(interval); // Clean up on unmount
  }, []);

  // Manual refresh button handler
  const handleRefresh = () => {
    setLoading(true);
    fetchMetrics(); // Trigger a manual refresh of data
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;

  return (
    <div>
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-semibold">Server Monitoring</h2>
        <button
          onClick={handleRefresh}
          className="px-4 py-2 bg-lightBlue-500 text-white rounded-md hover:bg-lightBlue-600"
        >
          Refresh
        </button>
      </div>

      {/* Display metrics */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 mt-4">
        {metrics.map((metric, index) => (
          <div
            key={index}
            className="p-4 bg-white rounded shadow-md border border-gray-200"
          >
            <h3 className="text-lg font-bold text-blue-600">
              Server: {metric.server_id}
            </h3>
            <p className="text-gray-700">
              <strong>CPU Usage:</strong> {metric.cpu_usage}%
            </p>
            <p className="text-gray-700">
              <strong>Memory Usage:</strong> {metric.memory_usage}%
            </p>
            <p className="text-gray-700">
              <strong>Disk Usage:</strong> {metric.disk_usage}%
            </p>
            <p className="text-gray-700">
              <strong>Uptime:</strong> {Math.floor(metric.uptime / 3600)} hrs
            </p>
            <p className="text-gray-500 text-sm">
              <strong>Timestamp:</strong> {new Date(metric.timestamp).toLocaleString()}
            </p>
            <details className="mt-2">
              <summary className="cursor-pointer text-blue-500">
                View Logs
              </summary>
              <ul className="bg-gray-100 p-2 rounded mt-1 text-gray-600">
                {JSON.parse(metric.logs).map((log, logIndex) => (
                  <li key={logIndex} className="text-sm">
                    {log}
                  </li>
                ))}
              </ul>
            </details>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MonitoringWidget;
